//! 🧪️ Genuine issued child custody and exact original parent handle addresses qualify funded Layout source dispatch.
use super::*;
use semio_framework_io_ports::{ChildAdmissionQualificationV1,ChildAdmissionStamp,ChildAdmissionRead,EmbeddedChildAdmitterV1,EmbeddedChildAdmission,erase_child_admission_source};
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneStep};
struct Qualified(ChildAdmissionStamp);
impl ChildAdmissionQualificationV1 for Qualified{fn child_admission_stamp(&self)->ChildAdmissionStamp{self.0}}
struct Registered;
static REGISTERED:Registered=Registered;
impl EmbeddedChildAdmitterV1 for Registered{fn birth_demand(&self)->RetirementDemand{Default::default()}fn begin(&self,_:RetainedCloneGrant)->Result<(EmbeddedChildAdmission,RetainedCloneProgress),ValueError>{Err(invalid("test registration selection only"))}}
impl semio_framework_io_ports::EmbeddedChildVectorSourceV1 for Registered{fn read_demand(&self)->RetirementDemand{Default::default()}fn read<'a>(&self,_:semio_framework_io_ports::ChildAdmissionSource<'a>,_:RetainedCloneGrant)->Result<semio_framework_io_ports::VectorGraphAdvance<'a>,ValueError>{Err(invalid("test vector selected but never polled"))}}
struct Provider{source:RetainedCloneSource<usize>,stamp:Qualified,calls:std::cell::Cell<usize>}
impl ChildAdmissionProviderV1 for Provider{fn read(&self,address:ChildAdmissionAddress)->Result<ChildAdmissionRead<'_>,ValueError>{self.calls.set(self.calls.get()+1);if address.ordinal()!=0||!address.matches(&self.stamp){return Err(invalid("foreign prepared original child"))}Ok(ChildAdmissionRead{source:erase_child_admission_source(self.source.borrow(),0x4348494c),admitter:&REGISTERED,vector:&REGISTERED})}}
#[test]
fn genuine_original_handle_source_dispatch_preserves_funded_absence_and_error_effects(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();assert_eq!(fixture["laws"].as_array().unwrap().len(),6);let g=RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:64};let mut snapshot=crate::snapshot::empty_layout_snapshot();let handle=store::os_store::artifact_child::ArtifactChild::new("drawing".into(),semio_framework_artifact_reference::ArtifactRef{dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.draw.drawing".into(),standard:"1".into(),subset:"*".into()},artifact_id:"draw-current".into()});snapshot.background_drawing=Some(LayoutDrawingMember{handle});let stamp=Qualified(ChildAdmissionStamp{parent_identity:&snapshot as*const _ as usize,expected_reference_identity:&snapshot.background_drawing.as_ref().unwrap().handle as*const _ as usize,child_identity:3,capability_identity:4,request_identity:5,parent_revision:[7;32],child_revision:[9;32]});let address=ChildAdmissionAddress::admit(0,&stamp,g).unwrap().0;let(source,_)=RetainedCloneSource::admit_owned(7usize,(),g).unwrap_or_else(|_|panic!("genuine original"));let mut provider=Provider{source,stamp,calls:Default::default()};for denied in [Default::default(),RetainedCloneGrant{maximum_copy_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let turn=drawing_read_at(&snapshot,DrawingSourceAddress::Document,&provider,address,denied).unwrap();assert!(!turn.done);assert_eq!(turn.progress,Default::default());}assert_eq!(provider.calls.get(),0);let turn=drawing_read_at(&snapshot,DrawingSourceAddress::Document,&provider,address,g).unwrap();assert!(turn.done);assert!(turn.progress.fits(g));assert_eq!(turn.read.unwrap().source.get().downcast_ref::<usize>(),Some(&7));let other=snapshot.clone();let error=drawing_read_at(&other,DrawingSourceAddress::Document,&provider,address,g).err().unwrap();assert_eq!(error.retained_progress().copied_bytes,drawing_read_demand().copy_bytes);let absent=crate::snapshot::empty_layout_snapshot();let turn=drawing_read_at(&absent,DrawingSourceAddress::Document,&provider,address,g).unwrap();assert!(turn.done&&turn.read.is_none());assert_eq!(turn.progress.copied_bytes,drawing_read_demand().copy_bytes);let error=drawing_read_at(&snapshot,DrawingSourceAddress::Page(999),&provider,address,g).err().unwrap();assert_eq!(error.retained_progress().copied_bytes,drawing_read_demand().copy_bytes);while !provider.source.terminal_is_empty(){let _step:RetainedCloneStep=provider.source.close_step(g).unwrap();}}
